beforeExample:
package test;

import org.eclipse.jdt.core.IJavaElement;
import org.eclipse.jdt.core.ILocalVariable;
import org.eclipse.jdt.core.JavaModelException;

public class Example {
    public void method(ILocalVariable lv) throws JavaModelException {
        IJavaElement parent = lv.getParent();
        System.out.println(parent.getElementName());
    }
}

afterExample:
package test;

import org.eclipse.jdt.core.IJavaElement;
import org.eclipse.jdt.core.ILocalVariable;
import org.eclipse.jdt.core.JavaModelException;

public class Example {
    public void method(ILocalVariable lv) throws JavaModelException {
        IJavaElement parent = lv.getDeclaringMember();
        System.out.println(parent.getElementName());
    }
}

negativeExample:
package test;

import org.eclipse.jdt.core.IJavaElement;
import org.eclipse.jdt.core.IMember;
import org.eclipse.jdt.core.ILocalVariable;

public class Example {
    public void anotherMethod(IMember member) {
        // Should not be transformed as 'member' is not ILocalVariable
        member.getParent();
    }

    public void checkJavaElementParent(IJavaElement element) {
        // Should not be transformed unless 'element' is specifically ILocalVariable
        element.getParent();
    }
}
